-- Unified seed extracted from all submissions
-- Compatible with the supplied PostgreSQL/Supabase schema.
-- Execute only in an empty database created from that schema.
BEGIN;




SELECT setval(pg_get_serial_sequence('public.especies', 'id'), COALESCE((SELECT MAX(id) FROM public.especies), 1), true);
SELECT setval(pg_get_serial_sequence('public.regioes', 'id'), COALESCE((SELECT MAX(id) FROM public.regioes), 1), true);
SELECT setval(pg_get_serial_sequence('public.observacoes', 'id'), COALESCE((SELECT MAX(id) FROM public.observacoes), 1), true);
COMMIT;